import sys

def lcs(X, Y):
    m = len(X)
    n = len(Y)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if X[i - 1] == Y[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp

def solve():
    import sys
    input = sys.stdin.read().split()
    n, m = map(int, input[:2])
    A, B = input[2], input[3]
    dp = lcs(A, B)
    max_score = 0
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if dp[i][j] > 0:
                score = 4 * dp[i][j] - i - j
                max_score = max(max_score, score)
    print(max_score)

solve()
